{
  "passageId": "horse-race-reporting",
  "items": [
    {
      "id": "R1",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시청자의 정보 요구와 방송사의 뉴스 공급 필요가 경마식 보도를 증가시키는 실제 유인으로 작용한다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "흥미에 치중하는 보도 성격이 주요 의제를 도외시하는 결과로 이어지는 실제 작용 관계이다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "흥미에 치중하는 보도 성격이 경쟁 결과에 집중하도록 만드는 실제 작용 관계이다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "주요 의제를 도외시하는 보도가 선거의 공정성을 저해할 수 있다는 부정적 영향 관계이다."
    },
    {
      "id": "R5",
      "type": "CAUSE",
      "otherName": "",
      "reason": "경쟁 결과에 집중하는 보도가 선거의 공정성을 저해할 수 있다는 실제 영향 관계이다."
    },
    {
      "id": "R6",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 경마식 보도가 참여 독려라는 장점을 가지면서도 공정성을 저해할 위험을 지닌다는 양면성을 제시한다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "경마식 보도의 문제점을 줄이기 위한 대응으로 법적 제한과 보도 준칙이 실제로 제시된다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "여론조사의 실시와 결과 보도라는 서로 다른 활동을 시기 제한의 유무라는 같은 기준으로 대비한다."
    },
    {
      "id": "R9",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "보도 금지 규정의 내용 소개에서 그 규정의 기본권 침해 여부를 심사하는 논의로 넘어간다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "선거 직전 보도가 선거에 영향을 줄 수 있다는 점이 보도 금지 규정에 대한 합헌 판단의 근거이다."
    },
    {
      "id": "R11",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "헌법재판소가 보도 금지 규정이라는 대상을 헌법적 기준에 따라 합헌으로 평가한 관계이다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "표본 오차를 감안하라는 일반적인 보도 요구를 오차 범위 내에서 허용되는 표현으로 구체화한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "표본 오차를 감안하라는 일반적인 보도 요구를 오차 범위 내 서열화 금지라는 세부 지침으로 풀어낸다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "표본 오차를 감안하라는 일반적인 보도 요구를 금지되는 우열 표현의 구체적 사례로 설명한다."
    },
    {
      "id": "R15",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "동일한 오차 범위 내 차이를 나타내는 두 표현을 사용 허용 여부라는 같은 기준으로 대비한다."
    },
    {
      "id": "R16",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "경마식 보도로 드러난 선거 방송의 한계에 대한 보완책으로 선거 방송 토론회를 제시한다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "후보자의 정책과 자질 차이를 드러내는 기능이 토론회를 경마식 보도의 보완책으로 활용할 수 있다는 판단을 뒷받침한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "초청 대상이 한정된다는 설명을 의석수·득표율·지지율에 따른 구체적인 법정 기준으로 풀어낸다."
    },
    {
      "id": "R19",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "초청 대상 제한으로 일부 후보자가 배제되는 문제를 보완하는 장치로 별도 토론회가 제시된다."
    },
    {
      "id": "R20",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "선거 방송 토론회의 기능과 운영 규정에 대한 설명에서 해당 규정의 위헌 여부에 대한 심사와 판단으로 논의가 넘어간다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "후보자가 너무 많으면 심층 토론이 어렵다는 점이 초청 제한을 합리적이라고 판단하는 근거이다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "후보자가 너무 많으면 관심이 큰 후보자들을 비교하기 어렵다는 점이 합리적 제한이라는 판단을 뒷받침한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "일부 후보자의 효과적인 선거 운동 기회를 박탈한다는 점이 자의적이고 차별적인 침해라는 판단의 근거이다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유권자가 모든 후보자를 동시에 비교하지 못한다는 점이 해당 규정을 차별적 침해로 판단하는 근거이다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "토론회 참여 여부에 따라 후보자를 차별적으로 인식하게 한다는 점이 차별적 침해라는 판단을 뒷받침한다."
    },
    {
      "id": "R26",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "동일한 토론회 규정에 대해 다수 의견은 합리적 제한으로, 소수 의견은 차별적 침해로 보는 견해 차이를 나란히 제시한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "다수 의견의 합리적 제한이라는 판단이 헌법재판소의 위헌이 아니라는 결정을 뒷받침하는 논거이다."
    },
    {
      "id": "R28",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "서로 다른 두 선거 관련 규정에 대한 헌법재판소의 판단이 모두 위헌이 아니라는 공통된 결과로 묶인다."
    }
  ]
}

